def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in into s_out"""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first position where they differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # One string is prefix of other
        if len(s_in) < len(s_out):
            # Insertion case
            return ("", s_out[len(s_in):], len(s_in))
        else:
            # Deletion case  
            return (s_in[len(s_out):], "", len(s_out))

    # Find what to replace at this position
    # For simplicity, let's assume single character replacement
    # But we need to be more careful about longer patterns

    # Try to find a substring that explains the difference
    # We'll look for longest matching prefix and suffix
    for length in range(min(len(s_in), len(s_out)), 0, -1):
        if s_in[pos:pos+length] == s_out[pos:pos+length]:
            # Found a match - so we're replacing s_in[pos:pos+length] with s_out[pos:pos+length]
            return (s_in[pos:pos+length], s_out[pos:pos+length], pos)

    # Default to single character
    return (s_in[pos], s_out[pos], pos)

